mapper.select:
select coalesce((
    select h.day_type
    from batch.business_calendar c
    join batch.calendar_holiday h
      on h.tenant_id = c.tenant_id
     and h.biz_date = #{bizDate}
     and (
         (h.scope = 'CALENDAR' and h.calendar_id = c.id)
         or (h.scope = 'GROUP' and h.group_code = c.group_code)
     )
    where c.tenant_id = #{tenantId}
      and c.calendar_code = #{calendarCode}
      and c.enabled = true
    order by case h.scope when 'CALENDAR' then 0 else 1 end
    limit 1
), 'WORKDAY')
